public class CounterRace {static class Counter{int value=0;void increment(){value++;}synchronized void safeIncrement(){value++;}}public static void main(String[] args)throws Exception{Counter c=new Counter();Thread[] t=new Thread[10];for(int i=0;i<t.length;i++){t[i]=new Thread(()->{for(int j=0;j<100000;j++)c.increment();});t[i].start();}for(Thread x:t)x.join();System.out.println("Without synchronization: "+c.value);c.value=0;for(int i=0;i<t.length;i++){t[i]=new Thread(()->{for(int j=0;j<100000;j++)c.safeIncrement();});t[i].start();}for(Thread x:t)x.join();System.out.println("With synchronization: "+c.value);}}
